#!/usr/bin/env node
// Builds the token outputs from tokens/*.json (decision D-028).
// Usage: node tools/build-tokens.mjs [tokens-dir]
// Writes tokens/build/tokens.css, tokens/build/_tokens.scss and tokens/build/tokens.json.
// Generated files; do not edit them by hand.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { TOKEN_FILES, flatten, resolveAll, isRef, refPath } from './lib/tokens.mjs';

const dir = process.argv[2] ?? 'tokens';
const outDir = join(dir, 'build');
const HEADER = 'Generated by tools/build-tokens.mjs from tokens/*.json. Do not edit.';

const tokens = TOKEN_FILES.flatMap((f) => flatten(JSON.parse(readFileSync(join(dir, f), 'utf8'))));
const resolved = resolveAll(tokens);
const byPath = new Map(tokens.map((t) => [t.path, t]));

// ---- value formatting ---------------------------------------------------------------------
const cssName = (path) => `--gg-${path.replace(/\./g, '-')}`;
const scssName = (path) => `$gg-${path.replace(/\./g, '-')}`;
const quoteFamily = (f) => (/^[a-z-]+$/.test(f) ? f : `'${f}'`);
const literal = (t, v) => {
  if (t.type === 'dimension') return typeof v === 'object' ? `${v.value}${v.unit}` : String(v);
  if (t.type === 'fontFamily') return (Array.isArray(v) ? v : [v]).map(quoteFamily).join(', ');
  return String(v);
};
// CSS keeps references as var() so a change to a primitive flows through its roles.
const cssValue = (t) => (isRef(t.value) ? `var(${cssName(refPath(t.value))})` : literal(t, t.value));
const scssValue = (t) => literal(t, resolved.get(t.path));

// ---- CSS: narrow type sizes by default, wide from breakpoint.m up ---------------------------
const isWide = (t) => /^type\.[^.]+\.wide\./.test(t.path);
const asNarrow = (path) => path.replace('.wide.', '.');
const asResponsive = (path) => path.replace(/\.(narrow|wide)\./, '.');
const breakpoint = literal(byPath.get('breakpoint.m'), resolved.get('breakpoint.m'));

const rootLines = [];
const wideLines = [];
for (const t of tokens) {
  if (isWide(t)) {
    wideLines.push(`    ${cssName(asNarrow(t.path))}: ${cssValue(t)};`);
  } else if (/^type\.[^.]+\.narrow\./.test(t.path)) {
    rootLines.push(`  ${cssName(asResponsive(t.path))}: ${cssValue(t)};`);
  } else {
    rootLines.push(`  ${cssName(t.path)}: ${cssValue(t)};`);
  }
}
// Wide values that reference narrow-named paths need the responsive name too.
const fixRef = (line) => line.replace(/var\(--gg-type-([a-z0-9]+)-(?:narrow|wide)-/g, 'var(--gg-type-$1-');
const css = [
  `/* ${HEADER} */`,
  ':root {',
  ...rootLines.map(fixRef),
  '}',
  '',
  `@media (min-width: ${breakpoint}) {`,
  '  :root {',
  ...wideLines.map(fixRef),
  '  }',
  '}',
  '',
].join('\n');

// ---- Sass: resolved variables, plus maps for the theme --------------------------------------
const scssVars = tokens.map((t) => `${scssName(t.path)}: ${scssValue(t)};`);
const families = [...new Set(tokens.filter((t) => t.path.startsWith('color.')).map((t) => t.path.split('.')[1]))];
const colorMap = families.map((f) => {
  const levels = tokens.filter((t) => t.path.startsWith(`color.${f}.`)).map((t) => `${t.path.split('.')[2]}: ${scssValue(t)}`);
  return `  ${f}: (${levels.join(', ')})`;
});
const roles = [...new Set(tokens.filter((t) => t.path.startsWith('type.')).map((t) => t.path.split('.')[1]))];
const typeMap = roles.map((r) => {
  const get = (p) => scssValue(byPath.get(`type.${r}.${p}`));
  return `  ${r}: (weight: ${get('weight')}, narrow: (size: ${get('narrow.size')}, line: ${get('narrow.line')}), wide: (size: ${get('wide.size')}, line: ${get('wide.line')}))`;
});
const scss = [
  `// ${HEADER}`,
  ...scssVars,
  '',
  '$gg-colors: (',
  colorMap.join(',\n'),
  ');',
  '',
  '$gg-type: (',
  typeMap.join(',\n'),
  ');',
  '',
].join('\n');

// ---- JSON: flat and resolved, for agents and the MCP server ---------------------------------
const flat = Object.fromEntries(tokens.map((t) => [t.path, { type: t.type, value: scssValue(t), ...(isRef(t.value) && { ref: refPath(t.value) }) }]));
const json = JSON.stringify({ $description: HEADER, tokens: flat }, null, 2) + '\n';

mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'tokens.css'), css);
writeFileSync(join(outDir, '_tokens.scss'), scss);
writeFileSync(join(outDir, 'tokens.json'), json);
console.log(`built ${tokens.length} tokens into ${outDir}: tokens.css, _tokens.scss, tokens.json`);
